<script setup>
import { pointsLabel } from '~~/shared/features/loyalty/points.js'
const page = ref(1)
const { data, error, status, refresh } = await useFetch('/api/account/points', { query: { page } })
const labels = { EARN: 'Ganancia', REDEEM: 'Canje', RESTORE: 'Restitución', REVERSE: 'Reversión', ADJUSTMENT: 'Ajuste' }
</script>
<template><section class="mt-8" aria-label="Mis puntos"><h2 class="text-display-m font-bold">Mis puntos</h2><UiLoading variant="list" v-if="status === 'pending'" label="Consultando puntos" /><div v-else-if="error" role="alert"><p>Puntos no disponibles.</p><UiButton @click="refresh">Reintentar</UiButton></div><template v-else-if="data"><dl class="mt-3 grid gap-2"><div><dt>Saldo contable</dt><dd>{{ pointsLabel(data.balanceTenths) }} puntos</dd></div><div><dt>Reservados</dt><dd>{{ pointsLabel(data.reservedTenths) }} puntos</dd></div><div><dt>Disponibles</dt><dd>{{ pointsLabel(data.availableTenths) }} puntos</dd></div></dl><p class="mt-3 text-body-s text-ink-2">Ganancias al entregar pedidos vinculados. Un punto equivale a $0.10 MXN en productos; el canje en checkout aún está pendiente de integrar.</p><p v-if="!data.movements.length" class="mt-3">Sin movimientos.</p><ul class="mt-3 grid gap-2"><li v-for="(entry,i) in data.movements" :key="i">{{ entry.date.slice(0,10) }} · {{ labels[entry.kind] }} · {{ pointsLabel(entry.deltaTenths) }} puntos · {{ entry.reason }}</li></ul><nav v-if="data.pages > 1" aria-label="Páginas de movimientos" class="mt-4 flex gap-4"><UiButton :disabled="page <= 1" @click="page--">Anterior</UiButton><span>{{ page }} / {{ data.pages }}</span><UiButton :disabled="page >= data.pages" @click="page++">Siguiente</UiButton></nav></template></section></template>
